let lang='ja', project=makeExample(), history=[], latest=null, revision=0, selected=[0,0], statusKey='ready', statusError=null;
const t = key => translations[lang][key];
const element = (tag, text, className) => { const node=document.createElement(tag); if(text!==undefined)node.textContent=text;if(className)node.className=className;return node; };
const exportButtons=['download-wif','download-svg','download-threading','download-report'];
function status(key,error=null){statusKey=key;statusError=error;$('status').textContent=error?(t('errors')[error.code]??t('errors').COMPILE):t(key);$('status').classList.toggle('error',!!error);}
function working(value){$('compile').disabled=value;$('cancel').hidden=!value;}
const session=new WorkSession({createWorker:()=>new Worker(new URL('./worker.mjs',import.meta.url),{type:'module'}),onResult:data=>{working(false);latest=data;renderResult();status(data.result.feasible?'complete':'blocked');},onError:error=>{working(false);status(null,error);}});
function invalidate(key='changed'){revision++;session.cancel();working(false);latest=null;$('result').hidden=true;$('empty-result').hidden=false;$('analysis').hidden=true;$('wif-compat').hidden=true;for(const id of exportButtons)$(id).disabled=true;status(key);}
function snapshot(){history.push(structuredClone(project));if(history.length>20)history.shift();$('undo').disabled=false;}
function currentProject(){return validateProject({...project,title:$('title').value,shaftCap:Number($('shaft-cap').value)});}
function syncFields(){$('title').value=project.title;$('shaft-cap').value=project.shaftCap;$('width').value=project.motif[0].length;$('height').value=project.motif.length;}
function renderGrid(){
 const grid=$('motif-grid');grid.replaceChildren();grid.setAttribute('aria-label',t('gridLabel'));const rows=project.motif.length,cols=project.motif[0].length;
 selected=[Math.min(selected[0],rows-1),Math.min(selected[1],cols-1)];grid.setAttribute('aria-rowcount',String(rows+1));grid.setAttribute('aria-colcount',String(cols+1));
 const header=element('div');header.setAttribute('role','row');header.append(element('span','', 'corner'));
 for(let c=0;c<cols;c++){const h=element('span',c+1);h.setAttribute('role','columnheader');header.append(h);}grid.append(header);
 for(let r=0;r<rows;r++){const row=element('div');row.setAttribute('role','row');const label=element('span',r+1);label.setAttribute('role','rowheader');row.append(label);
 for(let c=0;c<cols;c++){const cell=element('div');cell.setAttribute('role','gridcell');const button=element('button',undefined,'cell');button.type='button';button.dataset.row=r;button.dataset.col=c;button.setAttribute('aria-pressed',String(project.motif[r][c]));button.setAttribute('aria-label',t('cellLabel')(r+1,c+1,project.motif[r][c]));button.tabIndex=selected[0]===r&&selected[1]===c?0:-1;cell.append(button);row.append(cell);}grid.append(row);}
 $('dimensions').textContent=`${cols} × ${rows}`;
}
function moveFocus(r,c){const grid=$('motif-grid');grid.querySelector('button[tabindex="0"]')?.setAttribute('tabindex','-1');selected=[r,c];const button=grid.querySelector(`button[data-row="${r}"][data-col="${c}"]`);button.tabIndex=0;button.focus();}
$('motif-grid').addEventListener('click',event=>{const button=event.target.closest('button.cell');if(!button)return;const r=Number(button.dataset.row),c=Number(button.dataset.col);snapshot();project.motif[r][c]=!project.motif[r][c];invalidate();button.setAttribute('aria-pressed',String(project.motif[r][c]));button.setAttribute('aria-label',t('cellLabel')(r+1,c+1,project.motif[r][c]));moveFocus(r,c);});
$('motif-grid').addEventListener('keydown',event=>{const button=event.target.closest('button.cell');if(!button)return;let r=Number(button.dataset.row),c=Number(button.dataset.col);if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();if(event.key==='ArrowUp')r=Math.max(0,r-1);if(event.key==='ArrowDown')r=Math.min(project.motif.length-1,r+1);if(event.key==='ArrowLeft')c=Math.max(0,c-1);if(event.key==='ArrowRight')c=Math.min(project.motif[0].length-1,c+1);if(event.key==='Home')c=0;if(event.key==='End')c=project.motif[0].length-1;moveFocus(r,c);});
function renderPreview(motif){const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');const rows=motif.length,cols=motif[0].length;svg.setAttribute('viewBox',`0 0 ${cols*3} ${rows*3}`);svg.setAttribute('role','img');svg.setAttribute('aria-label',t('previewLabel'));const background=document.createElementNS(ns,'rect');background.setAttribute('width',cols*3);background.setAttribute('height',rows*3);background.setAttribute('fill','#edd7ab');svg.append(background);let d='';for(let r=0;r<rows*3;r++)for(let c=0;c<cols*3;c++)if(motif[r%rows][c%cols])d+=`M${c} ${r}h1v1h-1z`;const path=document.createElementNS(ns,'path');path.setAttribute('d',d);path.setAttribute('fill','#1f4749');svg.append(path);const edges=document.createElementNS(ns,'path');edges.setAttribute('d',`M${cols} 0v${rows*3}M${cols*2} 0v${rows*3}M0 ${rows}h${cols*3}M0 ${rows*2}h${cols*3}`);edges.setAttribute('stroke','#c0673e');edges.setAttribute('stroke-width','.1');svg.append(edges);$('repeat-preview').replaceChildren(svg);}
function renderResult(){if(!latest)return;const d=latest.result;$('empty-result').hidden=true;$('result').hidden=false;$('analysis').hidden=false;const summary=$('result-summary');summary.replaceChildren(element('strong',d.requiredShafts),element('span',t('shaftUnit')),element('span',`${d.checkedCells} ${t('verified')}`,'verified'));$('cap-failure').hidden=d.feasible;$('cap-failure').textContent=t('capError')(d.requiredShafts,d.project.shaftCap);
 const groups=$('groups');groups.replaceChildren();for(const g of d.groups){const row=element('div',undefined,'group'),content=element('div',undefined,'group-content');row.append(element('span',t('groupLabel')(g.shaft),'shaft-badge'));content.append(element('div',t('columns')(g.columns)),element('div',g.signature,'signature'));row.append(content);groups.append(row);}
 const witnesses=$('witnesses');witnesses.replaceChildren();for(const w of d.witnesses)witnesses.append(element('p',t('witness')(w)));if(!d.witnesses.length)witnesses.append(element('p',t('noPairs')));
 $('threading').replaceChildren(element('p',t('threadingLabel')),element('p',d.threading.map((s,i)=>`${i+1}→${s}`).join('  ·  '),'data-line'));
 $('liftplan').replaceChildren(element('p',t('liftLabel')),element('p',d.liftplan.map((ss,i)=>`${i+1}→${ss.join(',')||t('none')}`).join('  ·  '),'data-line'));
 renderPreview(d.project.motif);const floats=$('float-summary');floats.replaceChildren();const header=element('div',undefined,'float-header');for(const key of ['axis','finite','cyclic'])header.append(element('span',t(key)));floats.append(header);
 for(const axis of ['warp','weft'])for(const face of ['front','back']){const line=element('div',undefined,'float-row');line.append(element('span',`${t(axis)} · ${t(face)}`));for(const kind of ['finite','cyclic']){const value=d.floats.summary[axis][face][kind];line.append(element('strong',value.kind==='unbounded'?t('unbounded'):String(value.length)));}floats.append(line);}
 $('wif-compat').hidden=!d.warnings.includes('PYWEAVING_0_0_7_ZERO_LIFT');$('wif-compat').textContent=t('wifCompatibility');const f=d.floats;$('degenerate').hidden=!f.constantColumns.length&&!f.constantRows.length;$('degenerate').textContent=t('degenerate')(f.constantColumns,f.constantRows);for(const id of exportButtons)$(id).disabled=!d.feasible||!latest.files;
}
for(const kind of ['plain','twill','boundary'])$(`example-${kind}`).addEventListener('click',()=>{snapshot();project=makeExample(kind);selected=[0,0];invalidate();syncFields();renderGrid();});
for(const id of ['title','shaft-cap','width','height','project-json'])$(id).addEventListener('input',()=>{if(id==='title')project.title=$('title').value;if(id==='shaft-cap')project.shaftCap=Number($('shaft-cap').value);invalidate();});
$('resize').addEventListener('click',()=>{const cols=Number($('width').value),rows=Number($('height').value);if(!Number.isInteger(cols)||!Number.isInteger(rows)||cols<1||cols>32||rows<1||rows>32){invalidate();$('status').textContent=t('resizeError');$('status').classList.add('error');return;}snapshot();project.motif=Array.from({length:rows},(_,r)=>Array.from({length:cols},(_,c)=>project.motif[r]?.[c]??false));invalidate();renderGrid();});
$('undo').addEventListener('click',()=>{if(!history.length)return;project=history.pop();invalidate();syncFields();renderGrid();$('undo').disabled=!history.length;});
$('compile').addEventListener('click',()=>{invalidate();try{const input=currentProject();project=input;working(true);status('working');session.start(input);}catch(error){status(null,error);}});
$('cancel').addEventListener('click',()=>invalidate('cancelled'));
function download(name,text,type){let url;try{url=URL.createObjectURL(new Blob([text],{type}));const a=element('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);return true;}catch{if(url)URL.revokeObjectURL(url);status(null,{code:'DOWNLOAD'});return false;}}
for(const [id,name,type] of [['download-wif','draft-weft.wif','text/plain;charset=us-ascii'],['download-svg','draft-weft.svg','image/svg+xml;charset=utf-8'],['download-threading','draft-weft-threading.txt','text/plain;charset=utf-8'],['download-report','draft-weft-report.json','application/json']])$(id).addEventListener('click',()=>{if(latest?.result.feasible&&latest.files)download(name,latest.files[name],type);});
$('save-project').addEventListener('click',()=>{try{if(download('draft-weft-project.json',serializeProject(currentProject()),'application/json'))status('saveDone');}catch(error){status(null,error);}});
function applyProject(text){const parsed=parseProject(text);snapshot();project=parsed;selected=[0,0];invalidate('loadDone');syncFields();renderGrid();}
$('load-json').addEventListener('click',()=>{invalidate();try{applyProject($('project-json').value);}catch(error){status(null,error);}});
$('open-file').addEventListener('change',async()=>{const file=$('open-file').files[0];if(!file)return;invalidate();const id=revision;try{if(file.size>MAX_INPUT_BYTES)throw{code:'SIZE'};const text=await file.text();if(id!==revision)return;applyProject(text);}catch(error){if(id===revision)status(null,error.code?error:{code:'FILE'});}finally{$('open-file').value='';}});
$('language').addEventListener('change',()=>{lang=$('language').value;document.documentElement.lang=lang;for(const node of document.querySelectorAll('[data-i18n]'))node.textContent=t(node.dataset.i18n);renderGrid();renderResult();status(statusKey,statusError);});
window.addEventListener('pagehide',()=>session.cancel());
syncFields();renderGrid();status('ready');
